L["{unit} {{!are|are not}} in a party or raid"] = "{unit} {{!estás|no estás}} en un grupo o banda"
-- en: "Choose a unit for this condition."
L["Choose a unit for this condition."] = "Elige una unidad para esta condición."
-- en: "Group membership option is invalid."
L["Group membership option is invalid."] = "La opción de pertenencia al grupo no es válida."
